package main

import (
	"net/http"
	"strings"
	"sync"
	"time"
)

const (
	// servedCap is the servedIndex's entry ceiling: past it, touch
	// opportunistically drops entries older than servedMaxAge. The map must
	// not grow with the corpus; a pruned-then-re-read entry is simply
	// re-touched by the read that matters.
	servedCap = 4096

	// servedMaxAge is the prune age ceiling — long past playingWindow and
	// retentionGrace, so pruning can never drop an anchor a sweep could
	// still consult.
	servedMaxAge = 24 * time.Hour
)

// servedHit is one served (item, nonce) pair — the exact build directory a
// client fetch addressed.
type servedHit struct {
	item  string
	nonce string
}

// servedIndex is retention's third anchor (fix-live-session-eviction): the
// process-lifetime, mutex-guarded record of which (item, nonce) build
// directories the /media surface actually served, and when. The retention
// sweep's dual anchor — dir mtime + row updated_at — cannot see a live
// session (reads bump neither), which is how it once evicted a directory
// mid-playback into a 404 storm; this index is the read signal the sweeps
// consult. In-memory by design: a restart forgets served reads exactly like
// the suppressionSet forgets suppression marks (the accepted amnesia — the
// first sweep after a boot may take a build a pre-boot session was reading;
// the client's next fetch re-anchors it). No I/O under the lock. The
// methods tolerate a nil receiver: the no-index caller (and the
// signature-only test call sites) pass nil and the sweeps behave exactly as
// before.
type servedIndex struct {
	mu   sync.Mutex
	hits map[servedHit]time.Time
}

// newServedIndex builds the composition root's one served-read index.
func newServedIndex() *servedIndex {
	return &servedIndex{hits: make(map[servedHit]time.Time)}
}

// touch records that the /media surface served this (item, nonce) build.
func (s *servedIndex) touch(item, nonce string) {
	if s == nil || item == "" || nonce == "" {
		return
	}
	now := time.Now()
	s.mu.Lock()
	defer s.mu.Unlock()
	if len(s.hits) > servedCap {
		for k, t := range s.hits {
			if now.Sub(t) > servedMaxAge {
				delete(s.hits, k)
			}
		}
	}
	s.hits[servedHit{item: item, nonce: nonce}] = now
}

// recent reports whether this build directory was served within window.
func (s *servedIndex) recent(item, nonce string, window time.Duration) bool {
	if s == nil {
		return false
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	t, ok := s.hits[servedHit{item: item, nonce: nonce}]
	return ok && time.Since(t) <= window
}

// recentItems projects the index onto item ids: every item with at least
// one served read within window — the frontier's Playing input (a nil
// receiver reads as nothing-served).
func (s *servedIndex) recentItems(window time.Duration) map[string]bool {
	if s == nil {
		return nil
	}
	cutoff := time.Now().Add(-window)
	s.mu.Lock()
	defer s.mu.Unlock()
	out := make(map[string]bool)
	for h, t := range s.hits {
		if t.After(cutoff) {
			out[h.item] = true
		}
	}
	return out
}

// playingItems unions the two live-session signals at now: items whose
// playback-progress stamp is within playingWindow (recency, the watchState
// map) and items with a served build read within playingWindow — either
// alone can miss a session (a TV client may poll segments without posting
// progress, and a fresh play may not yet have fetched a segment).
func playingItems(recency map[string]time.Time, served *servedIndex, now time.Time) map[string]bool {
	out := make(map[string]bool)
	cutoff := now.Add(-playingWindow)
	for id, t := range recency {
		if t.After(cutoff) {
			out[id] = true
		}
	}
	for id := range served.recentItems(playingWindow) {
		out[id] = true
	}
	return out
}

// servedMedia wraps the /media handler so every GET/HEAD under
// /media/<item>/<nonce>/… records the served (item, nonce) BEFORE
// delegation — retention's third anchor must see the read even when the
// serve itself answers 404. /original and any non-/media path pass through
// untouched: originals are never policy-evicted artifacts. The path split
// mirrors stream.splitMediaPath's mount shape.
func servedMedia(next http.Handler, idx *servedIndex) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method == http.MethodGet || r.Method == http.MethodHead {
			if item, rest, ok := servedPath(r.URL.Path); ok && rest != "original" {
				if nonce, _, found := strings.Cut(rest, "/"); found {
					idx.touch(item, nonce)
				}
			}
		}
		next.ServeHTTP(w, r)
	})
}

// servedPath splits "/media/<item>/<rest>" — the web mount's path shape,
// the same split stream.splitMediaPath performs at the handler.
func servedPath(p string) (item, rest string, ok bool) {
	if !strings.HasPrefix(p, "/media/") {
		return "", "", false
	}
	item, rest, found := strings.Cut(strings.TrimPrefix(p, "/media/"), "/")
	if !found || item == "" || rest == "" {
		return "", "", false
	}
	return item, rest, true
}
